data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_006cca971c6aded6006aa7003c209087d2866347403a57107f","logprobs":[],"output_index":0,"sequence_number":276,"text":"{\"name\":\"Classic Margherita Pizza\",\"ingredients\":[\"1 pizza dough (store-bought or homemade)\",\"1 cup of crushed tomatoes (preferably San Marzano)\",\"8 oz fresh mozzarella cheese, sliced\",\"Fresh basil leaves\",\"2 tbsp olive oil\",\"Salt to taste\",\"Black pepper to taste\",\"Cornmeal (for dusting)\"],\"steps\":[\"Preheat your oven to the highest setting, usually around 475°F (245°C).\",\"If using a pizza stone, place it in the oven to preheat as well.\",\"On a lightly floured surface, roll out the pizza dough into a circle (about 12 inches in diameter).\",\"Transfer the rolled-out dough to a pizza peel or a baking sheet dusted with cornmeal to prevent sticking.\",\"Spread a thin layer of crushed tomatoes over the dough, leaving a little border around the edges.\",\"Arrange the fresh mozzarella slices evenly on top of the tomatoes.\",\"Drizzle olive oil over the pizza and season with salt and black pepper.\",\"Carefully slide the pizza onto the preheated pizza stone or place the baking sheet in the oven.\",\"Bake for about 8-12 minutes, or until the crust is golden and the cheese is bubbling and slightly browned.\",\"Remove the pizza from the oven and immediately top with fresh basil leaves.\",\"Let cool for a minute, slice, and serve hot.\"]}"}

